    /// <summary>아는 표준명들, 사람에게 보여 줄 순서로.</summary>
    public static IEnumerable<string> Names => Mso.Keys.Concat(new[] { "line", "textbox" }).OrderBy(x => x, StringComparer.Ordinal);

    /// <summary>부르는 말을 표준명으로. 모르는 이름은 <b>가장 가까운 것을 짚어</b> 거절한다.</summary>
    public static string Resolve(string? kind)
    {
        var raw = (kind ?? "").Trim();
        if (raw.Length == 0) return "textbox";
        var key = new string(raw.ToLowerInvariant().Where(c => c is not (' ' or '_' or '-')).ToArray());
        if (Alias.TryGetValue(key, out var got)) return got;
        var near = Names.Where(n => { var f = n.ToLowerInvariant();
            return f.Contains(key) || key.Contains(f)
                || f.StartsWith(key[..Math.Min(5, key.Length)]) || key.StartsWith(f[..Math.Min(5, f.Length)]); })
            .Take(5).ToList();
        throw new HandError($"{raw} 는 이 손이 아는 도형이 아닙니다"
            + (near.Count > 0 ? $" — 혹시 {string.Join(" · ", near)} 입니까?" : "")
            + " — 아는 것: " + string.Join(", ", Names));
    }
